CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_connections(id TEXT PRIMARY KEY, version INTEGER NOT NULL, active INTEGER NOT NULL, data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_connection_versions(connection_id TEXT NOT NULL REFERENCES model_connections(id), version INTEGER NOT NULL, data_json TEXT NOT NULL, encrypted_key TEXT NOT NULL, PRIMARY KEY(connection_id,version));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discussions(id TEXT PRIMARY KEY,status TEXT NOT NULL,version INTEGER NOT NULL,generation INTEGER NOT NULL,updated_at TEXT NOT NULL,data_json TEXT NOT NULL,host_connection_id TEXT,host_version INTEGER,FOREIGN KEY(host_connection_id,host_version) REFERENCES model_connection_versions(connection_id,version));
CREATE INDEX IF NOT EXISTS discussions_activity ON discussions(status,updated_at);
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,discussion_id TEXT NOT NULL REFERENCES discussions(id),data_json TEXT NOT NULL,UNIQUE(discussion_id,id));
CREATE TABLE IF NOT EXISTS agent_bindings(discussion_id TEXT NOT NULL,participant_id TEXT NOT NULL,connection_id TEXT NOT NULL,connection_version INTEGER NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(discussion_id,participant_id),FOREIGN KEY(discussion_id,participant_id) REFERENCES participants(discussion_id,id),FOREIGN KEY(connection_id,connection_version) REFERENCES model_connection_versions(connection_id,version));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,discussion_id TEXT NOT NULL REFERENCES discussions(id),message_seq INTEGER NOT NULL,turn_id TEXT NOT NULL,participant_id TEXT NOT NULL,reply_to_message_id TEXT,data_json TEXT NOT NULL,UNIQUE(discussion_id,id),UNIQUE(discussion_id,message_seq),UNIQUE(discussion_id,turn_id),FOREIGN KEY(discussion_id,participant_id) REFERENCES participants(discussion_id,id),FOREIGN KEY(discussion_id,reply_to_message_id) REFERENCES messages(discussion_id,id));
CREATE TABLE IF NOT EXISTS insights(discussion_id TEXT NOT NULL REFERENCES discussions(id),id TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(discussion_id,id));
CREATE TABLE IF NOT EXISTS insight_evidence(discussion_id TEXT NOT NULL,insight_id TEXT NOT NULL,message_id TEXT NOT NULL,relation TEXT NOT NULL,PRIMARY KEY(discussion_id,insight_id,message_id,relation),FOREIGN KEY(discussion_id,insight_id) REFERENCES insights(discussion_id,id) ON DELETE CASCADE,FOREIGN KEY(discussion_id,message_id) REFERENCES messages(discussion_id,id));
CREATE TABLE IF NOT EXISTS discussion_events(discussion_id TEXT NOT NULL REFERENCES discussions(id),event_seq INTEGER NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(discussion_id,event_seq));
CREATE TABLE IF NOT EXISTS command_receipts(scope TEXT NOT NULL,idempotency_key TEXT NOT NULL,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(scope,idempotency_key));
CREATE TABLE IF NOT EXISTS model_runs(id TEXT PRIMARY KEY,discussion_id TEXT REFERENCES discussions(id),participant_id TEXT,purpose TEXT NOT NULL,connection_id TEXT NOT NULL,connection_version INTEGER NOT NULL,model TEXT NOT NULL,prompt_version TEXT NOT NULL,latency_ms INTEGER NOT NULL,usage_json TEXT,error_code TEXT,created_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
